        vsnprintf(buff， sizeof (buff)， fmt， args);
        va_end(args);
        buff[sizeof (buff) - 1] = 0;
        if ((n = strlen(buff)) > 0 && buff[n-1] != '\n') {
                buff[n++] = '\n'; buff[n++] = '\0';
        }
- ------8<------cut-here------8<------
本地或远程攻击者可以发送精心构建的RPC请求，发送到rpc.mountd守护进程中，可导致拒绝服务攻击，或者以root用户权限在系统上执行任意指令。
