...
int mbfl_filt_conv_html_dec(int c, mbfl_convert_filter *filter)
{
   if (!filter-<status) {
        ...
    } else {
        if (c == ';') {
            ...
        } else {
           /* add character */
            buffer[filter-<status++] = c;
